function [cdf,upp,pdf] = dncf_exact_dp(f,m,n,lam1,lam2)
%DNCF_EXACT_DP cdf, upper tail and pdf of the doubly noncentral F in double precision.
%   F = (Q1/m)/(Q2/n), Q1 ~ chi^2_m(lam1), Q2 ~ chi^2_n(lam2) independent. Double Poisson
%   mixture of regularized incomplete beta functions I_x(a+j,b+k), a = m/2, b = n/2,
%   x = c/(1+c), c = m f/n. The incomplete beta values are generated by recurrences in the
%   additive direction (downward in the first parameter, upward in the second), so that the
%   cdf, the upper tail and the pdf are each sums of positive terms, without cancellation.
%   All recurrence terms are multiples of the beta densities
%      P(j,k) = x^(a+j-1) y^(b+k-1)/B(a+j,b+k),  y = 1-x,
%   which also give the pdf. Poisson weights below 1e-24 are omitted (omitted mass < 1e-21).
%   Raymond Kan (raymond.kan@rotman.utoronto.ca), 2026. Programs accompanying Broda and Kan,
%   "Saddlepoint expansions of arbitrary order for multivariate distribution functions"; free to use and modify with a citation of the paper.
c = m*f/n; x = c/(1+c); y = 1/(1+c); a = m/2; b = n/2; xy = x*y;
[j,wj] = pois(lam1); [k,wk] = pois(lam2);
aj = a + j; bk = b + k';                           % column, row
P = exp((aj-1)*log(x) + (bk-1)*log(y) + gammaln(aj+bk) - gammaln(aj) - gammaln(bk));
W = wj*wk';
% lower: Ilo(p,q) = I_x(aj(p),bk(q)); start at (aj(end),bk(1)), forward in b, downward in a
top = betainc(x,aj(end),bk(1)) + [0, cumsum(P(end,1:end-1)*xy./bk(1:end-1))];
Ilo = [flipud(cumsum(flipud(P(1:end-1,:)*xy./aj(1:end-1)),1)) + top; top];
% upper: Iup(p,q) = I_y(bk(q),aj(p)); start at (bk(end),aj(1)), forward in a, downward in b
col = betainc(y,bk(end),aj(1)) + [0; cumsum(P(1:end-1,end)*xy./aj(1:end-1))];
Iup = [fliplr(cumsum(fliplr(P(:,1:end-1)*xy./bk(1:end-1)),2)) + col, col];
cdf = sum(W(:).*Ilo(:)); upp = sum(W(:).*Iup(:));
pdf = sum(W(:).*P(:))*(m/n)*y^2;
end

function [j,w] = pois(lam)
mu = lam/2;
if mu == 0, j = 0; w = 1; return, end
s = 15*sqrt(mu+1) + 25;
j = (max(0,floor(mu-s)):ceil(mu+s))';
w = exp(-mu + j*log(mu) - gammaln(j+1));
keep = w >= 1e-24*max(w);
j = j(keep); w = w(keep);
end
